<script lang="ts">import '$lib/design/tokens.css'; import '$lib/components/commerce/store.css'; import AddToCart from '$lib/components/commerce/AddToCart.svelte'; import MiniCart from '$lib/components/commerce/MiniCart.svelte'; import type { PageData } from './$types'; let { data }: { data: PageData } = $props(); let product = $derived(data.product); const plain = (text: string) => text.replace(/<[^>]*>/g, ' ').replace(/\s+/g, ' ').trim(); function price(p: typeof product.prices) { const n = Number(p.price) / 10 ** p.currency_minor_unit; return `${new Intl.NumberFormat('fa-IR').format(p.currency_code === 'IRR' ? n / 10 : n)} تومان`; }</script>
<svelte:head><title>{product.name} | اینکورا</title><meta name="description" content={plain(product.short_description).slice(0, 155) || `مشاهده ${product.name} در اینکورا`} /></svelte:head><div class="inkora-theme inkora-store" dir="rtl"><header class="store-header"><div class="store-container store-header-inner"><a class="store-brand" href="/"><img src="/assets/brand/inkora-wordmark-temporary.svg" alt="اینکورا؛ نوشتار موقت برند" /></a><nav class="store-nav" aria-label="ناوبری فروشگاه"><a href="/shop">فروشگاه</a><a href="/cart">سبد</a><MiniCart /></nav></div></header><main class="store-container store-main"><p><a href="/shop">بازگشت به فروشگاه</a></p><article class="detail"><div class="store-card product-image detail-image">{#if product.images[0]}<img src={product.images[0].src} alt={product.images[0].alt || `تصویر محصول ${product.name}`} />{:else}<span>تصویر واقعی این محصول هنوز افزوده نشده است.</span>{/if}</div><div class="detail-copy"><h1>{product.name}</h1>{#if product.sku}<p>شناسه کالا: <bdi dir="ltr">{product.sku}</bdi></p>{/if}<p class="price">{price(product.prices)}</p><p class="stock">{product.is_in_stock ? 'موجود' : product.stock_availability.text || 'ناموجود'}</p><AddToCart id={product.id} enabled={product.is_purchasable && product.is_in_stock && !product.has_options} />{#if product.short_description}<p class="description">{plain(product.short_description)}</p>{/if}{#if product.description}<p class="description">{plain(product.description)}</p>{/if}</div></article></main></div>
